      survivors[id] = survivor;
      notes.add(
        'merged duplicate provider record "${twin.name}" onto '
        '"${survivor.name}" (same auth domain)',
      );
    }
    return (entries: [for (final id in order) survivors[id]!], notes: notes);
  }

