  late MemoryFileSystem fs;
  late JsonlSessionRepo repo;

  setUp(() {
    fs = MemoryFileSystem();
    repo = JsonlSessionRepo(fs: fs, sessionsRoot: '/sessions');
  });

  Future<Session> newSession({String cwd = '/work'}) {
    return repo.create(JsonlSessionCreateOptions(cwd: cwd));
  }

